// Package 6b precondition probe. Non-destructive with the read-only agent token:
// every DELETE/POST targets only synthetic items this research created, or ids that don't exist,
// and the POST body is invalid so no job could be created even with write scope.
import fs from "node:fs";
import { api, org, project } from "./lib.mjs";
const O = org(), P = project();
const run = JSON.parse(fs.readFileSync(new URL("./last-run.json", import.meta.url), "utf8"));
const fb = await api(`/projects/${O}/${P}/events/${run.feedbackId}/`);
const fbGroup = fb.json.groupID;
const probes = [
  ["OPTIONS", `/projects/${O}/${P}/replays/${run.replayId}/`],
  ["DELETE", `/projects/${O}/${P}/replays/${run.replayId}/`],
  ["OPTIONS", `/projects/${O}/${P}/replays/jobs/delete/`],
  ["GET", `/projects/${O}/${P}/replays/jobs/delete/`],
  ["POST", `/projects/${O}/${P}/replays/jobs/delete/`, { data: { rangeStart: "2026-09-02T00:00:00Z", rangeEnd: "2026-09-01T00:00:00Z", environments: [], query: "class_id:999001" } }],
  ["OPTIONS", `/organizations/${O}/issues/`],
  ["DELETE", `/organizations/${O}/issues/?id=999999999`],
  ["DELETE", `/organizations/${O}/issues/${fbGroup}/`],
  ["DELETE", `/projects/${O}/${P}/replays/jobs/nonexistent-route/`], // control: unknown route
  ["PUT", `/organizations/${O}/issues/?id=${fbGroup}`, { status: "unresolved" }] // control: event:write works
];
for (const [method, path, body] of probes) {
  const r = await api(path, { method, body });
  const allow = r.headers.get("allow");
  const detail = typeof r.json === "object" ? JSON.stringify(r.json).slice(0, 160) : String(r.json).slice(0, 60).replace(/\s+/g, " ");
  console.log(`${method.padEnd(7)} ${path.replaceAll(O, "<org>").replaceAll(P, "<proj>")} -> ${r.status}${allow ? ` allow=[${allow}]` : ""} ${detail}`);
}

