// Shared helpers for the Sentry replay/feedback research scripts.
//
// Load the env first:  set -a; . ~/.config/sentry-dev/pawtograder.env; set +a
// Nothing here prints env values. Only slugs, ids, status codes and sizes are logged.
import { createRequire } from "node:module";
import zlib from "node:zlib";
import crypto from "node:crypto";

const require = createRequire("/home/jon/platform/package.json");
export const core = require("@sentry/core");

const {
  createEnvelope,
  createEventEnvelopeHeaders,
  createTransport,
  dsnFromString,
  getEnvelopeEndpointWithUrlEncodedAuth,
  serializeEnvelope,
  uuid4
} = core;

export function env(name) {
  const v = process.env[name];
  if (!v) throw new Error(`missing env ${name} (load ~/.config/sentry-dev/pawtograder.env)`);
  return v;
}

export const SDK = { name: "sentry.javascript.nextjs", version: "10.3.0" };

// ---------- transport (the same createTransport the browser SDK uses, with a Node fetch makeRequest) ----------

export function makeTransport(dsnString = env("NEXT_PUBLIC_SENTRY_DSN")) {
  const dsn = dsnFromString(dsnString);
  const url = getEnvelopeEndpointWithUrlEncodedAuth(dsn, undefined, SDK);
  const transport = createTransport(
    { recordDroppedEvent: () => {}, bufferSize: 30 },
    async (request) => {
      const res = await fetch(url, {
        method: "POST",
        body: request.body,
