/** Polls fn() every intervalMs until it returns a truthy value or timeoutMs passes. */
export async function poll(fn, { timeoutMs = 60000, intervalMs = 3000 } = {}) {
  const start = Date.now();
  for (;;) {
    const v = await fn();
    if (v) return { value: v, elapsedMs: Date.now() - start };
    if (Date.now() - start > timeoutMs) return { value: null, elapsedMs: Date.now() - start };
    await new Promise((r) => setTimeout(r, intervalMs));
  }
}

