// Runs the nightly H spec with the READ-ONLY agent token standing in for the purge token, to check
// the envelope and lookup half. Deletes answer 403, so nothing outside the test's own items could be touched.
// Prints nothing from the env files.
import { spawnSync } from "node:child_process";
import fs from "node:fs";
const parse = (p) =>
  Object.fromEntries(
    fs
      .readFileSync(p, "utf8")
      .split("\n")
      .filter((l) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(l))
      .map((l) => {
        const i = l.indexOf("=");
        return [l.slice(0, i), l.slice(i + 1).replace(/^["']|["']$/g, "")];
      })
  );
const local = parse("/home/jon/platform/.env.local");
const sentry = parse("/home/jon/.config/sentry-dev/pawtograder.env");
const env = {
  ...process.env,
  SUPABASE_URL: local.SUPABASE_URL,
  SUPABASE_SERVICE_ROLE_KEY: local.SUPABASE_SERVICE_ROLE_KEY,
  ...sentry,
  SENTRY_PURGE_TOKEN: sentry.SENTRY_AUTH_TOKEN
};
const r = spawnSync(
  "deno",
  ["test", "--no-check", "--allow-env", "--allow-net", "--allow-read", "bug-report-retention-purge/retentionPurge.nightly.ts"],
  { cwd: process.argv[2], env, encoding: "utf8" }
);
const redact = (s) => Object.values(sentry).concat(local.SUPABASE_SERVICE_ROLE_KEY ?? []).reduce((a, v) => (v && v.length > 6 ? a.split(v).join("<redacted>") : a), s);
console.log(redact(r.stdout).slice(-4000));
console.log(redact(r.stderr).slice(-3000));

