  Object.fromEntries(
    fs
      .readFileSync(p, "utf8")
      .split("\n")
      .filter((l) => /^[A-Za-z_][A-Za-z0-9_]*=/.test(l))
      .map((l) => {
        const i = l.indexOf("=");
        return [l.slice(0, i), l.slice(i + 1).replace(/^["']|["']$/g, "")];
      })
  );
const local = parse("/home/jon/platform/.env.local");
const sentry = parse("/home/jon/.config/sentry-dev/pawtograder.env");
const env = {
  ...process.env,
  SUPABASE_URL: local.SUPABASE_URL,
