// Read-only check of the purge's list and guard calls against the dev Sentry. No deletes.
import { SentryPurgeApi } from "/home/jon/platform/.claude/worktrees/agent-a92d7f148c6bba316/supabase/functions/bug-report-retention-purge/purge.ts";
const api = new SentryPurgeApi({
  baseUrl: Deno.env.get("SENTRY_URL")!,
  org: Deno.env.get("SENTRY_ORG")!,
  replayProject: Deno.env.get("SENTRY_PROJECT")!,
  token: Deno.env.get("SENTRY_AUTH_TOKEN")!
});
const pid = await api.replayProjectId();
console.log("project id resolved:", /^\d+$/.test(pid));
for (const cls of [999001, 99900, 9990]) {
  const issues = await api.listFeedbackIssues(cls);
  let match = 0;
  for (const i of issues ?? []) if (i.category === "feedback" && (await api.feedbackTagMatches(i.id, cls))) match++;
  const replays = await api.listReplays(pid, cls);
  console.log(`class ${cls}: feedback listed=${issues?.length} guard-pass=${match} replays listed=${replays?.length}`);
}
// the guard against a mismatched class: the 999001 issue checked as class 99900
const issues = await api.listFeedbackIssues(999001);
if (issues?.[0]) console.log("guard for wrong class:", await api.feedbackTagMatches(issues[0].id, 99900));

